1	import { useEffect, useState, type FormEvent } from 'react';
2	
3	// Opened from the clients list: a client's detail view lists the projects done for them, scoped to
4	// the client via /api/clients/<id>/projects. Reuses the project-row-<id>/project-name anchors so the
5	// listing reads the same way wherever projects appear. It also keeps the client's contacts (name,
6	// email, role), scoped the same way via /api/clients/<id>/contacts, with a form to add one.
7	type Project = { id: number; name: string };
8	type Contact = { id: number; name: string; email: string; role: string };
9	type Counts = { projects: number; contacts: number };
10	
11	// A contact must carry a proper email address too, same guard as clients: a single non-whitespace
12	// local part, an @, and a dotted domain.
13	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
14	
15	export function ClientDetail({ clientId }: { clientId: number }) {
16	  const [projects, setProjects] = useState<Project[]>([]);
17	  const [contacts, setContacts] = useState<Contact[]>([]);
18	  const [counts, setCounts] = useState<Counts>({ projects: 0, contacts: 0 });
19	  const [name, setName] = useState('');
20	  const [email, setEmail] = useState('');
21	  const [role, setRole] = useState('');
22	  const [emailError, setEmailError] = useState(false);
23	
24	  async function loadContacts() {
25	    const res = await fetch(`/api/clients/${clientId}/contacts`);
26	    if (res.ok) {
27	      setContacts(await res.json());
28	    }
29	  }
30	
31	  // The at-a-glance counts of projects and contacts come from the server, counted in SQL.
32	  async function loadCounts() {
33	    const res = await fetch(`/api/clients/${clientId}/counts`);
34	    if (res.ok) {
35	      setCounts(await res.json());
36	    }
37	  }
38	
39	  useEffect(() => {
40	    async function load() {
41	      const res = await fetch(`/api/clients/${clientId}/projects`);
42	      if (res.ok) {
43	        setProjects(await res.json());
44	      }
45	    }
46	    void load();
47	    void loadContacts();
48	    void loadCounts();
